INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('2', 'Business', '', '0', '0', '0', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('1', 'Scheduler', 'The scheduler of the program: the tasks and the feed of notes under every one of them - the same lists the owner and the staff see in their windows. Add-only, the way the program keeps it: a task is never edited nor deleted, it moves by a note carrying a state, and kClose ends it. A private task is seen by its author, its executor and the person with id 1. state_key and kind_key are values of TASK_STATE_KEY and TASK_KIND_KEY in the base settings, and the people go by id - the Users tool answers them.', '2', '1', '1', '0', 'melbis_agent_task.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('33', 'Currencies', 'The currencies the prices of the store are written in. multiplex is the rate against the base currency - the one whose rate is 1 - and division says a sum is divided by that rate instead of multiplied. A goods points at a currency by its *_curr_id columns and the Prices tool writes them; the sums already written into orders keep their own words and never follow a currency.', '2', '1', '2', '0', 'melbis_agent_currency.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('34', 'Providers', 'The providers of the goods, the groups they stand in and the options hung on them. The option tree - provider_key with the values of provider_key_value - belongs to the program and is only read here; the providers, their groups and the rows of provider_key_set are what this tool writes. A goods points at its provider by store.provider_id, the Prices tool writes it, and a currency of one provider points back by currency.provider_id.', '2', '1', '3', '0', 'melbis_agent_provider.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('35', 'Discounts', 'The discount groups of the store and the rules standing in them. A goods carries a group by store.disc_group_id - the Prices tool writes it - and the rules of that group say what the discount is: from_sum is where a rule starts, disc_proc is how much it takes off, and the two days are the ones it lives between. A group holding no rule gives nothing away. A rule writes its currency in sum_curr_id, and the Currencies tool answers those.', '2', '1', '4', '0', 'melbis_agent_disc.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('9', 'Products', '', '0', '0', '5', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('12', 'Brands', 'The brands of the goods and the options hung on them. The option tree - brand_key with the values of brand_key_value - belongs to the program and is only read here; the brand rows and the rows of brand_key_set are what this tool writes. A goods wears a brand by its brand_id column, and the Prices tool writes it.', '9', '1', '6', '0', 'melbis_agent_brand.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('30', 'Goods', '', '9', '1', '7', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('29', 'List', 'Finding the goods of this store - the one way to look for them, and the only one that answers just what this person may see: the right of a goods comes from the sections it hangs in. Two ways to ask - by the sections the goods lie in, or by the fields of the goods themselves. The rows come as the store table keeps them; what is written on a goods is changed by other tools - the Descriptions for the content, the Prices for the money.', '30', '2', '8', '0', 'melbis_agent_store_list.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('15', 'Prices', 'The commercial half of a goods: what it costs and how many there are - the prices with their currencies, the supplier, the discount group, the stock, the auto-count and the parameters standing on it. The right is for_price, given out in the program on the sections a goods hangs in, so only goods hanging in a section of yours are reached here. The other half - the names and the texts a buyer reads - belongs to the Descriptions tool.', '30', '2', '9', '0', 'melbis_agent_store_price.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('14', 'Descriptions', 'The content half of a goods: what a buyer reads about it - the names, the codes, the texts, the seo, the clan and the characteristics standing on it. The very fields the Descriptions window of the program writes back, the price among them, though the money proper belongs to the Prices tool. The right is for_frame, given out in the program on the sections a goods hangs in, so only goods hanging in a section of yours are reached here.', '30', '2', '10', '0', 'melbis_agent_store_descr.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('23', 'Location', 'Where a goods hangs in the catalogue and in what order it stands there - the rows of topic_store and nothing else. The right is the Location one, given out on the section: the section takes the goods in, so whoever owns the section decides. A goods hanging in no section is in the store and in no catalogue at all, and only the Recovery tool reaches it.', '30', '2', '11', '0', 'melbis_agent_store_place.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('24', 'Recovery', 'The goods that hang in no section at all - the Recovery window of the program. Such a goods is in the store and in no catalogue: no storefront reaches it and no other tool of the goods sees it, because the right over a goods comes from the sections it hangs in. CmdLink puts it back, CmdRemove ends it - and this is the one door in the store where a goods is deleted.', '30', '2', '12', '0', 'melbis_agent_store_lost.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('39', 'Import', '', '9', '1', '13', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('37', 'Goods', 'The loader of the goods: everything a card is made of in one call. Four streams tied by ref, a temporary key of your own - the goods, their characteristics, their parameters, and the sections they hang in. Keys are not weighed here: brands, providers, currencies and the tree of the characteristics are read beforehand and come as ids; only a value of a characteristic may come as a word, and it is looked up under its info_id. The pictures are a call of their own: the store lays a file down before a module runs, and a goods not born yet has nothing to hang it on - take the ids of this answer to the Files tool.', '39', '2', '14', '0', 'melbis_agent_import_goods.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('38', 'Files', 'The loader of the files: a pack of them onto the elements in one call, and a derived picture painted beside those that ask for one. It is the second half of an import and goes after the goods: a file hangs on an element by its id, and the ids are what the answer of the Goods loader gave back - write them into the rows of this call. The files themselves ride with the call, so the size of one pack is the size of one request: split a big load into several calls.', '39', '2', '15', '0', 'melbis_agent_import_files.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('6', 'Structure', '', '0', '0', '16', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('8', 'Catalog', 'The sections of the main catalogue: the tree itself, the rights on it, the options hung on it and the alternative catalogues built over it. Every row of an answer says what this person may do on that very section, so read the list before promising anything. The goods themselves are not touched here - only the places they hang in, and the Location tool moves them.', '6', '1', '17', '0', 'melbis_agent_topic.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('10', 'Attributes', 'What a buyer reads about a goods: the tree of the characteristics with its folders, and the values every one of them takes. The tree comes whole, the values are asked for by their characteristic - a live shop keeps thousands of them. The rights are a pair - the characteristic itself and its values - and they are given out on the characteristic, in the program.', '6', '1', '18', '0', 'melbis_agent_info.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('11', 'Parameters', 'The parameters of the goods: the commercial properties the prices are built of - warranty, delivery, a margin of its own - and the values each one takes, every value with the sum it carries and the currency of that sum. Not what a buyer reads about the goods: that is the characteristics, and the Attributes tool keeps them.', '6', '1', '19', '0', 'melbis_agent_param.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('21', 'Files', '', '0', '0', '20', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('22', 'File', 'The files of the elements - the photographs of the goods above all. One tool for every element, because one table shape serves them all: a file is a row of files_<entity> and a picture on the disk. The group of a file (kind_key) is what a template picks it by, and the group words are values of the FILES_<ENTITY> codes in the base settings. The right is that of the element the file hangs on. No tool deletes a picture from the disk: rows go, and the idle-files audit of the owner reclaims the space.', '21', '1', '21', '0', 'melbis_agent_file.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('27', 'Profile', 'The picture profiles: the recipes a derived picture is made by - size, type, quality, margins, background, rotation, mask, effects. A profile is a row of the FILES_PROFILE dictionary, but its body is XML of the program\'s editor, so it is read and written here, in plain words. The frame of a picture is cut by hand in the program; everything else a profile keeps. A mask is a value of FILES_MASK in the base settings with a picture hung on it by the Files tool - entity key_value, elem_id the id of that value.', '21', '1', '22', '0', 'melbis_agent_file_profile.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('7', 'Development', '', '0', '0', '23', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('5', 'Settings', 'The registry of the settings of this shop: the base lists the whole program picks from, and the settings the people of the shop change themselves.', '7', '1', '24', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('31', 'Basic settings', 'The base settings of the shop: the tree of the codes and the values every code keeps - the lists the whole program picks from, from the kind of a goods to the style of a section. The tree of the codes belongs to the platform and is only read; the values are what this tool writes. A value marked sys_key is one the platform relies on by its very name: its text may be changed, but not that name, and it cannot be removed.', '5', '2', '25', '0', 'melbis_agent_key_value.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('32', 'User settings', 'The settings the people of the shop change themselves: the groups in a tree, and in every group the settings with the mask their text is typed by, plus the rights that say who sees a group. What the storefront reads out of them is the business of the modules.', '5', '2', '26', '0', 'melbis_agent_self_key.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('3', 'System', '', '0', '0', '27', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('4', 'Users', 'The people of the shop, the groups they stand in and the rights they hold - a right is an operation of the oper tree, handed to a person or to a group. A password is never a field of a call: it is born in the tool, kept as md5 and said once. What a person did in the shop keeps their id, so one who carries history is blocked rather than deleted.', '3', '1', '28', '0', 'melbis_agent_user.php');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('257', '1', 'CmdList', 'Reads every task this person may see, the closed ones too - kClose tells them apart - and counts the notes of each, so a feed is asked for knowingly. Takes GET_SCHED_TASK.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('258', '1', 'CmdAdd', 'Adds a task and opens its feed with the first note, the way the program opens one. The person of this session signs as the author, and the state at birth is kNew. Takes ADD_SCHED_TASK.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('259', '1', 'CmdNoteList', 'Reads the feed of a task whole, the notes in the order they were written. Takes GET_SCHED_NOTE.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('260', '1', 'CmdNoteAdd', 'Writes a note into the feed of one task; the state says whether the task moves with it - kComment leaves it where it stands, any other state moves it and kClose ends it. exec_id, kind_key and privy given here move with the task. Takes ADD_SCHED_NOTE.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('222', '4', 'CmdList', 'Reads the people, the groups, the tree of the operations and the rights - five tables whole. oper holds every operation of the program and gives its id, a row of oper_right hands an operation to a person or to a group, and oper_table says which tables an operation carries. The md5 of a password is not among the columns and never leaves the base. Takes GET_USERS.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('223', '4', 'CmdAdd', 'Adds a person. There is no password field: the tool makes one, keeps its md5 only and says the password once in the answer - hand it over, advise to change it, store it nowhere. Rights are given out with CmdRightAdd. Takes PUT_USERS.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('224', '4', 'CmdUpdate', 'Changes the columns given of people, by id - what the call leaves out stays as it was. A login changes for one person at a time, and blocking is here too: is_blocked. Takes PUT_USERS.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('225', '4', 'CmdRemove', 'Deletes people by id, with the rows of their rights. A person who carries history - tasks, notes, memory - is refused: block them instead. The person of this session is refused too. Takes PUT_USERS.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('226', '4', 'CmdPassword', 'Makes a new password for one person, said once and kept as md5 only. The old one stops working at once. Takes PUT_USERS.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('227', '4', 'CmdGroupAdd', 'Adds a group of people at the end of the list. Its rights are given out with CmdRightAdd. Takes PUT_USERS.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('228', '4', 'CmdGroupUpdate', 'Changes the columns given of groups, by id - what the call leaves out stays as it was. Takes PUT_USERS.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('229', '4', 'CmdGroupRemove', 'Deletes groups by id, with the rows of their rights. A group that people still stand in is refused - move them out of it first. Takes PUT_USERS.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('230', '4', 'CmdGroupPos', 'Lays the list of the groups in order. Takes PUT_USERS.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('231', '4', 'CmdRightAdd', 'Grants an operation to a person or to a group, one of the two - the other stays empty. A right by group reaches everyone whose group_id or add_group_id it is. The person with id 1 holds every operation without a single row here, and the oper tree itself belongs to the engine: no tool writes it. Takes PUT_USERS.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('232', '4', 'CmdRightUpdate', 'Changes the columns given of the right rows, by id. A right does not move from a person to a group: take it back and give it out anew. Takes PUT_USERS.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('233', '4', 'CmdRightRemove', 'Takes rights back by id. The other rights of those people stay. Takes PUT_USERS.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('151', '8', 'CmdList', 'Reads the whole catalogue at once and the five tables that hang off it: the sections with the shape of the tree, the rights on every section, the alternative catalogues, the tree of the options with the values those options keep, and what is set on every section - six tables. The two tables of the option tree are read so that key_id and value_id can be filled from them. Nothing narrows it and nothing is hidden: who may do what on a section is in topic_right, and it comes along.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('152', '8', 'CmdAdd', 'Adds a section under a parent. The rights of the parent are copied onto it, so the same people own it; the parent itself must be yours to shape.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('153', '8', 'CmdUpdate', 'Changes the columns given of sections, by id - what the call leaves out stays as it was.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('154', '8', 'CmdMove', 'Moves a section under another parent, with its whole branch. Both the section and the new parent must be yours to shape, and a section cannot move inside its own branch.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('155', '8', 'CmdRemove', 'Deletes sections by id, with everything lying under them. The first call counts the sections and the goods it touches, the second one does it: the goods stay in the store, and the ones left hanging nowhere are reached by the Recovery tool alone.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('156', '8', 'CmdRightAdd', 'Grants a right on sections, to a person or to a group: one row of topic_right on each of them. One of user_id and group_id, never both. Takes PUT_TOPIC_RIGHT - handing out rights is not itself a right on a section.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('157', '8', 'CmdRightUpdate', 'Changes the columns given of the rows of topic_right, by id - CmdList answers them with their ids. Takes PUT_TOPIC_RIGHT.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('158', '8', 'CmdRightRemove', 'Deletes the rows of topic_right by id. A section left with no rights on it is seen only by whoever holds PUT_TOPIC_RIGHT. Takes PUT_TOPIC_RIGHT.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('159', '8', 'CmdKeyAdd', 'Sets an option on sections: one row of topic_key_set on each of them. The option and its value must stand in the tree of the section options, and a stray id is refused; the sections must be yours to shape.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('160', '8', 'CmdKeyUpdate', 'Changes the columns given of the rows of topic_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('161', '8', 'CmdKeyRemove', 'Deletes the rows of topic_key_set by id. The option itself stays in the registry.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('162', '8', 'CmdAltAdd', 'Adds a node of an alternative catalogue under a parent of the same catalogue. Every node stands for a section of the main catalogue - the name may differ, the section may not be missing, and a node pointing at nothing is swept away. Takes PUT_TOPIC_ALT.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('163', '8', 'CmdAltUpdate', 'Changes the columns given of the nodes of the alternative catalogues, by id. Takes PUT_TOPIC_ALT.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('164', '8', 'CmdAltMove', 'Moves a node under another parent of its own catalogue, with its whole branch. The kind comes from the node itself, so a node never leaves its catalogue. Takes PUT_TOPIC_ALT.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('165', '8', 'CmdAltRemove', 'Deletes nodes by id, with the branches under them - the sections they point at stay as they are. The first call counts what goes, the second one does it. Takes PUT_TOPIC_ALT.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('176', '10', 'CmdList', 'Reads the whole tree of the characteristics and the four tables that hang off it: the rights on every one of them, the tree of the options with the values those options keep, what is set on every characteristic, and how many values each one holds - six tables. The two tables of the option tree are read so that key_id and value_id can be filled from them. The values themselves are CmdValueList.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('177', '10', 'CmdAdd', 'Adds a characteristic under a parent, or at the top of the tree when parent_id is 0. The rights of the parent are copied onto it. Takes ADD_FAST_INFO.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('178', '10', 'CmdUpdate', 'Changes the columns given of characteristics, by id - what the call leaves out stays as it was. Takes RENAME_FAST_INFO.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('179', '10', 'CmdMove', 'Moves a characteristic under another parent, with its whole branch. Takes MOVE_FAST_INFO.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('180', '10', 'CmdRemove', 'Deletes characteristics by id, with the branch under them, their values and the links of the goods to those values. The first call counts what goes, the second one does it. Takes DELETE_FAST_INFO.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('181', '10', 'CmdValueList', 'Reads the values of characteristics, or the values themselves by id. One of info_id and id is asked for: nothing answers every value of the shop. Takes GET_INFO_VALUE.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('182', '10', 'CmdValueAdd', 'Adds a value to a characteristic, at the end of its list. Takes PUT_INFO_VALUE and the value right on that characteristic.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('183', '10', 'CmdValueUpdate', 'Changes the columns given of values, by id - what the call leaves out stays as it was. Takes PUT_INFO_VALUE.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('184', '10', 'CmdValueRemove', 'Deletes values by id, with the links of the goods to them - the characteristic itself stays. The first call counts what goes, the second one does it. Takes PUT_INFO_VALUE.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('185', '10', 'CmdValuePos', 'Lays the values of one characteristic in order. Takes PUT_INFO_VALUE.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('186', '10', 'CmdRightAdd', 'Grants a right on characteristics, to a person or to a group: one row of info_right on each of them. One of user_id and group_id, never both. Takes PUT_INFO_RIGHT - handing out rights is not itself a right on a characteristic.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('187', '10', 'CmdRightUpdate', 'Changes the columns given of the rows of info_right, by id - CmdList answers them with their ids. Takes PUT_INFO_RIGHT.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('188', '10', 'CmdRightRemove', 'Deletes the rows of info_right by id. Takes PUT_INFO_RIGHT.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('189', '10', 'CmdKeyAdd', 'Sets an option on characteristics: one row of info_key_set on each of them. The option and its value must stand in the tree of the characteristic options, and a stray id is refused. Takes PUT_INFO_KEY_SET.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('190', '10', 'CmdKeyUpdate', 'Changes the columns given of the rows of info_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree. Takes PUT_INFO_KEY_SET.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('191', '10', 'CmdKeyRemove', 'Deletes the rows of info_key_set by id. The option itself stays in the registry. Takes PUT_INFO_KEY_SET.', '16');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('167', '11', 'CmdList', 'Reads the parameters and every value of them - both tables whole; the dictionaries of this shop are small and nothing narrows them. Takes GET_PARAM.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('168', '11', 'CmdAdd', 'Adds a parameter at the end of the list. fixed_set keeps the goods to the values of its list and nothing of their own; custom_sum lets the sum be changed on the goods. Takes PUT_PARAM.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('169', '11', 'CmdUpdate', 'Changes the columns given of parameters, by id - what the call leaves out stays as it was. Takes PUT_PARAM.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('170', '11', 'CmdRemove', 'Deletes parameters by id, with their values and the links of the goods to them. The first call counts what goes, the second one does it; the prices built on those sums change. Takes PUT_PARAM.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('171', '11', 'CmdPos', 'Lays the list of the parameters in order. Takes PUT_PARAM.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('172', '11', 'CmdValueAdd', 'Adds a value to a parameter, at the end of its list. Takes PUT_PARAM.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('173', '11', 'CmdValueUpdate', 'Changes the columns given of values, by id - what the call leaves out stays as it was. Takes PUT_PARAM.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('174', '11', 'CmdValueRemove', 'Deletes values by id, with the links of the goods to them - the parameter itself stays. The first call counts what goes, the second one does it; the prices built on those sums change. Takes PUT_PARAM.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('175', '11', 'CmdValuePos', 'Lays the values of one parameter in order. Takes PUT_PARAM.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('239', '12', 'CmdList', 'Reads the brands, the tree of their options with the values those options keep, and what is set on every brand - four tables. The two tables of the tree are read so that key_id and value_id can be filled from them. Takes GET_BRAND.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('240', '12', 'CmdAdd', 'Adds a brand at the end of the list. Takes PUT_BRAND.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('241', '12', 'CmdUpdate', 'Changes the columns given of brands, by id - what the call leaves out stays as it was. Takes PUT_BRAND.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('242', '12', 'CmdRemove', 'Deletes brands by id. The first call counts the goods wearing them, the second one does it: the goods stay in the store with an emptied brand_id, and what hung on the brands - the option rows and the file rows - is swept by the map of the engine. Takes PUT_BRAND.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('243', '12', 'CmdPos', 'Lays the list of the brands in order. Takes PUT_BRAND.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('244', '12', 'CmdKeyAdd', 'Sets an option on brands: one row of brand_key_set on each of them. The option and its value must stand in the tree of the brand options, and a stray id is refused. Takes PUT_BRAND.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('245', '12', 'CmdKeyUpdate', 'Changes the columns given of the rows of brand_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree. Takes PUT_BRAND.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('246', '12', 'CmdKeyRemove', 'Deletes the rows of brand_key_set by id. The option itself stays in the tree. Takes PUT_BRAND.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('142', '14', 'CmdList', 'Reads the content half: the row of every goods, the sections it hangs in, the characteristics standing on it and the objects tied to it - four tables. One of store_id and topic_id is enough, and topic_sub takes in everything lying under those sections.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('166', '14', 'CmdAdd', 'Adds a goods and hangs it in the section at once - a goods hanging nowhere is seen by the Recovery tool alone. Every column of the half may come in the same call; the days left out are stamped now, and a fresh goods is born hidden, out of stock and plain. The section must be yours to describe.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('143', '14', 'CmdUpdate', 'Changes the columns given, on one goods or on several at once - each of them gets the same written. What the call leaves out stays as it was, and update_time and edit_time are stamped now unless the call carries its own. A goods hanging in no section of yours is refused by id.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('144', '14', 'CmdInfoAdd', 'Sets a characteristic on goods: one row of store_info on each of them, and a characteristic holding several values at once takes a row for each. The characteristic itself comes from the Attributes tool - a value of its list goes by value_id, a number by value_dec, a text of your own by value_txt.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('145', '14', 'CmdInfoUpdate', 'Changes the columns given of the rows of store_info; a row keeps whatever the call leaves out. CmdList answers the rows of a goods with their ids.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('146', '14', 'CmdInfoRemove', 'Deletes the rows of store_info by id. The characteristic itself stays in the store, and the goods keeps the other ones standing on it.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('147', '14', 'CmdSetAdd', 'Ties another object of the store to goods: one row of store_set on each of them. obj_key says what is tied - a goods or a section - and kind_key what the tie means; the storefront reads that: accessories, a kit, a section to send to.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('148', '14', 'CmdSetUpdate', 'Changes the columns given of the rows of store_set; a row keeps whatever the call leaves out. CmdList answers the rows of a goods with their ids.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('149', '14', 'CmdSetRemove', 'Deletes the rows of store_set by id. The object it tied stays in the store.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('150', '14', 'CmdClannNew', 'Makes a fresh clan over two or more goods - the variants of one thing - with one of them leading it. Putting one more goods into a clan that already stands is CmdUpdate with its clann.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('71', '15', 'CmdList', 'Reads the commercial half: the row of every goods, the sections it hangs in and the parameters standing on it - three tables. One of store_id and topic_id is enough, and topic_sub takes in everything lying under those sections.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('129', '15', 'CmdAdd', 'Adds a goods and hangs it in the section at once - a goods hanging nowhere is seen by the Recovery tool alone. Every column of the half may come in the same call; the days left out are stamped now, and a fresh goods is born hidden and out of stock. The section must be yours to price.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('73', '15', 'CmdUpdate', 'Changes the columns given, on one goods or on several at once - each of them gets the same written. What the call leaves out stays as it was, and update_time is stamped now unless the call carries its own. A goods hanging in no section of yours is refused by id.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('130', '15', 'CmdUnlink', 'Takes goods out of one section; the goods themselves stay in the store with every other section they hang in. The answer names the ones left hanging nowhere - only the Recovery tool reaches those.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('131', '15', 'CmdParamAdd', 'Sets a parameter on goods: one row of store_param on each of them, at the end of that parameter\'s rows. A value of the parameter\'s own list goes by value_id, a value of your own by value_name.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('132', '15', 'CmdParamUpdate', 'Changes the columns given of the rows of store_param; a row keeps whatever the call leaves out. CmdList answers the rows of a goods with their ids.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('133', '15', 'CmdParamRemove', 'Deletes the rows of store_param by id. The parameter itself stays in the store and the goods keeps its other parameters.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('247', '22', 'CmdList', 'Reads the files of elements - whole rows of files_<entity>, in the order a template walks them. Takes the right of those elements.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('248', '22', 'CmdAdd', 'Hangs the files that ride with the call on their elements: every entry carries its path, its entity and its elem_id, and may carry kind_key and real_name. The store lays each file down before the tool runs and weighs the group by the registry; the picture is kept as it came - nothing here resizes or crops it. Takes the right of the elements.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('249', '22', 'CmdMake', 'Paints a second picture out of one already in the store, by a profile of the Profiles tool: fitted into its box, the canvas behind, the mask over, the effects GD paints. What GD cannot paint - the grey wash - is left out and said in the answer. The new row lands in the group the recipe names. Takes the right of the element.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('250', '22', 'CmdUpdate', 'Changes the columns given of file rows, by id; the pictures themselves are not touched. Takes the right of the elements they hang on.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('251', '22', 'CmdRemove', 'Deletes file rows by id. The pictures stay on the disk until the owner runs the idle-files audit: nothing in this store deletes a file from there. Takes the right of the elements.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('252', '22', 'CmdPos', 'Lays one group of one element in order - the order a template walks the pictures in. Takes the right of the element.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('134', '23', 'CmdList', 'Reads the links of sections or of goods: the rows of topic_store with their order, and the goods themselves as the Location window of the program shows them - two tables. One of topic_id and store_id is enough, and both may come at once.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('135', '23', 'CmdLink', 'Hangs goods into a section, each at the end of it. A goods already standing there is left as it is and said in the answer.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('136', '23', 'CmdUpdate', 'Moves links into another section, each at the end of it - the goods keep every other section they hang in. CmdList answers the links with their ids.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('137', '23', 'CmdUnlink', 'Deletes links by id. The goods stay in the store; one left hanging nowhere is said in the answer, and only the Recovery tool reaches it after that.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('138', '23', 'CmdPos', 'Lays the goods of one section in order - the order the storefront walks them by.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('139', '24', 'CmdList', 'Reads the goods hanging nowhere, as the Recovery window of the program shows them. Every field narrows the answer by a part of that column. Takes GET_REMOVE_STORE.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('140', '24', 'CmdLink', 'Hangs a lost goods back into a section, at the end of it. Takes RESTORE_REMOVE_STORE and the Location right on that section; a goods already hanging somewhere belongs to the Location tool.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('141', '24', 'CmdRemove', 'Deletes a lost goods from the store for good, with everything hanging on it - its characteristics, its parameters, its files. The first call counts what goes, the second one does it. Takes DELETE_REMOVE_STORE.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('253', '27', 'CmdList', 'Reads the profiles, every recipe in plain words.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('254', '27', 'CmdAdd', 'Adds a profile: the name and the two sides are asked for, the rest of the recipe takes its defaults. The word of the profile is what CmdMake of the Files tool runs by.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('255', '27', 'CmdUpdate', 'Changes the fields given of one profile, the rest stay as they were; rename gives it a new word.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('256', '27', 'CmdRemove', 'Takes one profile out of the registry; a profile the program relies on is refused. Pictures already derived by it stay where they hang.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('126', '29', 'CmdTopicList', 'Reads the goods of sections. Several sections come as a list, and topic_sub takes in everything lying under them.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('127', '29', 'CmdSearchList', 'Reads the goods holding what the call asks for. Every field narrows the answer further; a field given a list is satisfied by any of its values, and a range takes two values - from and to - or one alone as the floor.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('234', '31', 'CmdList', 'Reads the tree of the codes and every value of them - both tables whole. The tree belongs to the platform: codes are not added, moved or removed by any tool. Takes GET_KEY_VALUE.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('235', '31', 'CmdValueAdd', 'Adds a value to a code, at the end of its list. Takes PUT_KEY_VALUE.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('236', '31', 'CmdValueUpdate', 'Changes the columns given of values, by id. The text of a value the platform relies on (sys_key) may be changed; its name may not. Takes PUT_KEY_VALUE.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('237', '31', 'CmdValueRemove', 'Deletes values by id. What already holds such a value keeps the word: nothing of the shop is rewritten behind it. A value the platform relies on (sys_key) is refused. Takes PUT_KEY_VALUE.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('238', '31', 'CmdValuePos', 'Lays the values of one code in order. Takes PUT_KEY_VALUE.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('201', '32', 'CmdList', 'Reads the whole tree of the groups, the rights on them and every setting in them - three tables. Takes GET_USER_KEY.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('202', '32', 'CmdAdd', 'Adds a group under a parent, or at the top of the tree when parent_id is 0. Takes UPDATE_USER_KEY.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('203', '32', 'CmdUpdate', 'Changes the columns given of groups, by id - what the call leaves out stays as it was. Takes UPDATE_USER_KEY.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('204', '32', 'CmdMove', 'Moves a group under another parent, with its branch. Takes UPDATE_USER_KEY.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('205', '32', 'CmdRemove', 'Deletes groups by id, with the branch under them, the settings in them and the rights on them. The first call counts what goes, the second one does it. Takes UPDATE_USER_KEY.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('206', '32', 'CmdValueAdd', 'Adds a setting to a group, at the end of its list. Takes UPDATE_USER_KEY.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('207', '32', 'CmdValueUpdate', 'Changes the columns given of settings, by id - what the call leaves out stays as it was. Takes UPDATE_USER_KEY.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('208', '32', 'CmdValueRemove', 'Deletes settings by id. The group they stood in stays. Takes UPDATE_USER_KEY.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('209', '32', 'CmdValuePos', 'Lays the settings of one group in order. Takes UPDATE_USER_KEY.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('210', '32', 'CmdRightAdd', 'Grants the sight of groups, to a person or to a group of people: one row of self_key_right on each of them. One of user_id and group_id, never both. Takes UPDATE_USER_KEY.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('211', '32', 'CmdRightUpdate', 'Changes the columns given of the rows of self_key_right, by id - CmdList answers them with their ids. Takes UPDATE_USER_KEY.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('212', '32', 'CmdRightRemove', 'Deletes the rows of self_key_right by id. A group with no rights on it is seen by nobody. Takes UPDATE_USER_KEY.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('261', '33', 'CmdList', 'Reads the currency table whole. Takes GET_CURRENCY.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('262', '33', 'CmdAdd', 'Adds a currency at the end of the list. The rate comes as 1 when the call leaves it out - the program adds one the same way - so give the real multiplex right away. Takes PUT_CURRENCY.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('263', '33', 'CmdUpdate', 'Changes the columns given of currencies, by id - what the call leaves out stays as it was. Takes PUT_CURRENCY.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('264', '33', 'CmdRemove', 'Deletes currencies by id. The first call counts the goods priced in them, the second one does it: their *_curr_id columns are emptied, so those prices read as the base currency, and the sums already written into orders stay as written. Takes PUT_CURRENCY.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('265', '33', 'CmdPos', 'Lays the list of the currencies in order. Takes PUT_CURRENCY.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('266', '34', 'CmdList', 'Reads the providers, their groups, the tree of the options with the values those options keep, and what is set on every provider - five tables. The two tables of the tree are read so that key_id and value_id can be filled from them. Takes GET_PROVIDER.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('267', '34', 'CmdAdd', 'Adds a provider at the end of the list. Takes PUT_PROVIDER.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('268', '34', 'CmdUpdate', 'Changes the columns given of providers, by id - what the call leaves out stays as it was. Takes PUT_PROVIDER.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('269', '34', 'CmdRemove', 'Deletes providers by id. The first call counts the goods and the currencies pointing at them, the second one does it: store.provider_id and currency.provider_id are emptied, the rows that hung on the providers are swept by the map of the engine, and what orders already carry stays as written. Takes PUT_PROVIDER.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('270', '34', 'CmdPos', 'Lays the list of the providers in order. Takes PUT_PROVIDER.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('271', '34', 'CmdGroupAdd', 'Adds a group of providers at the end of the list. Takes PUT_PROVIDER.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('272', '34', 'CmdGroupUpdate', 'Changes the columns given of groups, by id. Takes PUT_PROVIDER.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('273', '34', 'CmdGroupRemove', 'Deletes groups by id. A group that providers still stand in is refused - move them out of it first. Takes PUT_PROVIDER.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('274', '34', 'CmdGroupPos', 'Lays the list of the groups in order. Takes PUT_PROVIDER.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('275', '34', 'CmdKeyAdd', 'Sets an option on providers: one row of provider_key_set on each of them. The option and its value must stand in the tree of the provider options, and a stray id is refused. Takes PUT_PROVIDER.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('276', '34', 'CmdKeyUpdate', 'Changes the columns given of the rows of provider_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree. Takes PUT_PROVIDER.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('277', '34', 'CmdKeyRemove', 'Deletes the rows of provider_key_set by id. The option itself stays in the tree. Takes PUT_PROVIDER.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('278', '35', 'CmdList', 'Reads the discount groups and every rule in them - both tables whole. Takes GET_DISCOUNT.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('279', '35', 'CmdAdd', 'Adds a discount group at the end of the list. It gives nothing away until a rule stands in it. Takes PUT_DISCOUNT.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('280', '35', 'CmdUpdate', 'Changes the columns given of groups, by id - what the call leaves out stays as it was. Takes PUT_DISCOUNT.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('281', '35', 'CmdRemove', 'Deletes discount groups by id. The first call counts the goods priced by them, the second one does it: store.disc_group_id is emptied, so those goods sell without a discount, and the rules of the groups go with them. Takes PUT_DISCOUNT.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('282', '35', 'CmdPos', 'Lays the list of the discount groups in order. Takes PUT_DISCOUNT.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('283', '35', 'CmdRateAdd', 'Adds a rule to discount groups: one row of disc_rate on each of them. The rules of one group stand by from_sum, so several of them make a ladder; the days are opened the way the program opens them - from now, for ten years. Takes PUT_DISCOUNT.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('284', '35', 'CmdRateUpdate', 'Changes the columns given of rules, by id - CmdList answers them with their ids. A rule does not move to another group: take it back and add it anew. Takes PUT_DISCOUNT.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('285', '35', 'CmdRateRemove', 'Deletes rules by id. The group stays, and gives nothing away while it holds no rule. Takes PUT_DISCOUNT.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('287', '37', 'CmdAdd', 'Loads goods with their sections, their characteristics and their parameters in one call. Each stream is a list of rows - the array itself, or {"file": "C:\\\\...\\\\rows.jsonl"} on your machine, one row per line. A field whose name begins with store_, info_ or param_ is what every row of that stream takes unless the row names its own. Every section must be yours by both the Descriptions and the Prices right. The answer gives a row per goods - your ref beside the id it was born with - and that is what the Files tool takes for the pictures. Takes PUT_INFO_VALUE when value_add adds a value.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('288', '38', 'CmdAdd', 'Hangs a pack of files on their elements and paints a derived picture where a profile asks for one. A file whose element is not yours goes back at once and is said in the answer. Takes the right of those elements, and no setting right with it: a derived picture is a file, not a setting.', '1');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('408', '71', 'store_id', 'id of the goods, or several of them', 'int/json', '0', '', '1');
